tool_input.command:
$ud = Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data'
foreach ($n in 'SODA','SODALanguagePacks') { $p = Join-Path $ud $n; if (Test-Path $p) { $s = (Get-ChildItem $p -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum; "{0}: {1:N1} MB" -f $n, ($s/1MB); Get-ChildItem $p -Directory | ForEach-Object { $ss=(Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum; "   {0}  {1:N1} MB" -f $_.Name, ($ss/1MB) } } else { "$n: absent" } }
'--- chrome versions (directory names only, nothing executed)'
foreach ($r in "$env:ProgramFiles\Google\Chrome\Application","${env:ProgramFiles(x86)}\Google\Chrome\Application","$env:LOCALAPPDATA\Google\Chrome\Application") { if (Test-Path $r) { $r; Get-ChildItem $r -Directory | Where-Object { $_.Name -match '^\d+\.' } | Select-Object -ExpandProperty Name } }
'--- policy keys'
foreach ($k in 'HKLM:\SOFTWARE\Policies\Google\Chrome','HKCU:\SOFTWARE\Policies\Google\Chrome') { if (Test-Path $k) { "$k present"; (Get-Item $k).Property } else { "$k absent" } }
'--- disk'
Get-PSDrive C,E | ForEach-Object { "{0}: free {1:N1} GB of {2:N1} GB" -f $_.Name, ($_.Free/1GB), (($_.Used+$_.Free)/1GB) }
$env:COMPUTERNAME
